import * as T from './vendor/three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
export function createCampus(canvas){const r=new T.WebGLRenderer({canvas,antialias:true,alpha:true});r.setPixelRatio(Math.min(devicePixelRatio,1.6));r.outputColorSpace=T.SRGBColorSpace;r.toneMapping=T.ACESFilmicToneMapping;const s=new T.Scene(),c=new T.PerspectiveCamera(70,1,.1,120);c.position.set(0,2.75,-5.65);s.add(new T.HemisphereLight(0xe7edf0,0x7d796e,2));const sun=new T.DirectionalLight(0xffe3b9,3);sun.position.set(-5,6,1);s.add(sun);let disposed=false,raf;new GLTFLoader().load('assets/classroom.glb',g=>{if(disposed)return;g.scene.traverse(o=>{if(/Screen_(title|subtitle)|Screen (title|subtitle)/.test(o.name))o.visible=false;});s.add(g.scene);const board=document.createElement('canvas');board.width=1400;board.height=800;const ctx=board.getContext('2d');ctx.fillStyle='#e9eee8';ctx.fillRect(0,0,1400,800);ctx.fillStyle='#174b3b';ctx.textAlign='center';ctx.font='bold 90px sans-serif';ctx.fillText('ЦЕНТР ИНВЕСТ БАНК',700,370);ctx.font='36px sans-serif';ctx.fillText('УЧЕБНАЯ ЛАБОРАТОРИЯ / IT',700,470);const tex=new T.CanvasTexture(board);tex.colorSpace=T.SRGBColorSpace;const sign=new T.Mesh(new T.PlaneGeometry(3.28,1.88),new T.MeshBasicMaterial({map:tex}));sign.position.set(0,2.62,5.59);sign.rotation.y=Math.PI;s.add(sign);canvas.classList.add('ready');},undefined,()=>canvas.classList.add('failed'));let dx=0,dy=0;canvas.onpointermove=e=>{const b=canvas.getBoundingClientRect();dx=(e.clientX-b.left)/b.width-.5;dy=(e.clientY-b.top)/b.height-.5;};function frame(){raf=requestAnimationFrame(frame);if(document.hidden)return;let w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;if(canvas.width!==Math.floor(w*r.getPixelRatio())||canvas.height!==Math.floor(h*r.getPixelRatio()))r.setSize(w,h,false);c.aspect=w/h;c.lookAt(dx*.55,1.8-dy*.2,3);c.updateProjectionMatrix();r.render(s,c);}frame();return{dispose(){disposed=true;cancelAnimationFrame(raf);s.traverse(o=>{o.geometry?.dispose();const ms=Array.isArray(o.material)?o.material:[o.material];ms.filter(Boolean).forEach(m=>{m.map?.dispose();m.dispose();});});r.dispose();}};}
